import type {ToolId} from "./tools";
import {planningContent} from "./planning-content";
export type ToolContent={formula:string;explanation:string[];example:string;tips:string[];sections:{heading:string;paragraphs:string[]}[];faq:{question:string;answer:string}[];sources:{title:string;url:string;checkedOn?:string}[];related:string[]};
const cfpb={title:"CFPB: Auto loan terms and disclosures",url:"https://www.consumerfinance.gov/consumer-tools/auto-loans/answers/key-terms/",checkedOn:"2026-10-15"};
const ftc={title:"FTC: Buying a used car from a dealer",url:"https://consumer.ftc.gov/articles/buying-used-car-dealer"};
const fuelSource={title:"DOE/EPA: Fuel economy and fuel costs",url:"https://www.fueleconomy.gov/feg/savemoney.jsp",checkedOn:"2026-10-15"};
export const toolContent:Record<ToolId,ToolContent>={
...planningContent,
loan:{formula:"P = max(0, price + financed sales tax + title + registration + other financed fees + old loan payoff − down payment − trade allowance)\nr = annual interest rate ÷ 1,200\nM = P × r ÷ (1 − (1 + r)^(−n))\nAt 0% interest: M = P ÷ n",explanation:["P is the amount financed, r is the monthly interest rate, and n is the number of scheduled monthly payments. The calculator assumes the same rate throughout the term and payments at the end of each month. Interest is calculated on the outstanding balance; the rest of each payment reduces principal.","Each schedule row rounds interest and payment to cents. The final installment clears the remaining balance. Extra payments are applied to principal after that month’s interest and can shorten the loan. The quoted regular payment remains visible so that you can distinguish the required payment from your voluntary overpayment. If down payment and trade credit exceed the full purchase cost and old payoff, financing is zero. Unallocated credit is reported separately; it is not a promised cash refund."],example:"A $25,000 car with $5,000 down, no trade or financed fees, and a 7% annual interest rate creates a $20,000 loan. Over 60 months, the estimated regular payment is $396.02. These inputs are illustrative; 7% is not a current offer. Adding $100 per month pays down the balance sooner and reduces the modeled interest.",tips:["Request a written out-the-door price before choosing a loan. Separate optional products from the vehicle price.","Compare loans with the same amount financed. A lower monthly payment alone does not mean a lower total cost.","Ask whether extra payments reduce principal immediately and whether prepayment charges apply.","Get a dated payoff quote for your trade. A statement balance may omit accrued interest or fees."],sections:[{heading:"Read the rate and the term together",paragraphs:["APR and the contract interest rate are related but not always identical. APR includes certain borrowing costs, while the monthly calculation needs the rate used to accrue interest. Enter the contract interest rate when available. If you only know APR, treating it as the interest rate gives an approximation, particularly when prepaid fees are material. Compare the lender’s Truth in Lending disclosures before signing.","A longer loan spreads principal over more months. That usually lowers the required payment but increases total interest when the rate and amount are unchanged. It also leaves the balance outstanding longer. Use the term comparison to decide whether a smaller purchase or a larger down payment is more useful than stretching the repayment period."]},{heading:"Why your lender’s schedule may differ",paragraphs:["Many auto loans accrue simple interest daily. The number of days between payments, the first due date, and late or early payments can change the allocation. This tool uses monthly periods, so its schedule is a budgeting estimate rather than a payoff statement. Do not send a final payment based only on the last row.","If a trade is worth less than its payoff, the negative equity is added to the new amount financed. That can leave you owing more than the replacement car is worth. Compare the new loan balance with a conservative resale estimate and consider whether postponing the purchase reduces that risk."]}],faq:[{question:"Can I calculate a 0% loan?",answer:"Yes. At zero interest, principal is divided by the term. The last payment reconciles rounding. Confirm whether choosing a promotional rate means giving up a rebate."},{question:"Are sales tax and dealer fees included?",answer:"Only the dollar amounts you enter in financed sales tax, title, registration and other financed charges. Enter each cost once. Cash-paid charges stay outside the loan. Use the tax estimator to calculate a verified-rate tax scenario first."},{question:"Does an extra payment reduce the regular payment?",answer:"Not in this model. It reduces the balance and can shorten payoff time. A lender may handle prepayments differently; ask about principal-only application."},{question:"What happens when I owe more than my trade is worth?",answer:"The payoff minus trade allowance increases the financed amount. For example, a $5,000 trade with an $8,000 payoff adds $3,000 before other purchase costs."},{question:"Is this a loan approval or rate quote?",answer:"No. The tool does not check credit, contact lenders, or retrieve offers. Eligibility and contract terms require an actual lender decision."}],sources:[cfpb,{title:"CFPB: How amortization affects an auto loan",url:"https://www.consumerfinance.gov/ask-cfpb/what-is-amortization-and-how-could-it-affect-my-auto-loan-en-771/",checkedOn:"2026-10-15"}],related:["car-affordability-calculator","total-cost-of-ownership-calculator","car-sales-tax-calculator"]},
depreciation:{formula:"V₀ = starting value\nVₜ = V₀ × (1 − first decline/100) × (1 − annual decline/100)^(t−1)\nTotal depreciation = starting value − ending value",explanation:["The first decline applies once, in the first year of your projection. The later decline compounds on the previous year’s remaining value. A 12% annual decline therefore removes fewer dollars each year as the modeled value gets smaller. The chart and table show the same calculation.","A used car does not start depreciating anew when you buy it. Enter its current purchase or supported market value as the starting value, then choose assumptions for your upcoming ownership period. The default 18% and 12% declines are illustrative scenarios, not measured averages or make-specific forecasts."],example:"Start with a $30,000 value and assume a 20% decline in the first projected year, followed by 10% annually. The modeled values are $24,000 after year one, $21,600 after year two, and $19,440 after year three. Total modeled depreciation is $10,560. Actual sale proceeds may be higher or lower.",tips:["Use comparable vehicles that are a few years older to check whether your residual assumption is plausible.","Run at least three scenarios instead of relying on a single smooth curve.","Separate depreciation from the remaining loan balance. Losing value and repaying principal are different processes.","Include disposal costs or repairs separately when estimating net sale proceeds."],sections:[{heading:"Choose assumptions for the car you will actually own",paragraphs:["Age alone cannot explain every price difference. Mileage, condition, accident history, service documentation, options, powertrain, supply, and local demand all matter. A generic curve cannot capture a shortage, a discontinued model, a costly mechanical pattern, or a change in incentives for new vehicles. That is why the percentages remain editable.","For a practical budget, begin with the price you are likely to pay rather than the seller’s first asking price. Compare older examples with a similar trim and expected odometer reading. Listings are asking prices, not confirmed transaction prices, but they can reveal when a proposed residual is implausibly optimistic."]},{heading:"Use the curve to compare ownership periods",paragraphs:["A one-year purchase can be sensitive to transaction costs as well as value loss. Sales tax, registration, dealer fees, and selling costs are not included here. A longer ownership period may spread those costs over more years, but maintenance exposure can increase. Send your chosen residual to a full ownership-cost comparison before deciding.","At zero projected years, the result equals the starting value. A 100% first-year decline produces zero modeled residual. Negative depreciation rates are not supported, so this tool does not model appreciation. A collectible vehicle or unusual market is a reason to seek specialist comparables rather than force a standard curve to fit."]}],faq:[{question:"Are the default rates based on live prices?",answer:"No. They are transparent planning assumptions. The tool has no vehicle listing feed, transaction database, or appraisal integration."},{question:"Which price should I enter for a used car?",answer:"Use its current value or expected purchase price. The first-year percentage then applies to the next year you own it, not the original year of manufacture."},{question:"Can a vehicle lose more than these estimates?",answer:"Yes. Condition changes, accidents, repairs, demand, and local market conditions can produce losses a smooth curve does not predict."},{question:"Does depreciation include loan interest?",answer:"No. It is the difference between starting and ending vehicle value. Interest and operating costs belong in a separate ownership-cost budget."},{question:"Why does the dollar loss shrink over time?",answer:"The annual percentage is applied to a declining balance. The same percentage of a smaller value is a smaller dollar amount."}],sources:[ftc],related:["what-is-my-car-worth","total-cost-of-ownership-calculator","trade-in-value-estimator"]},
value:{formula:"Base = original base MSRP × 0.82 × 0.88^(age−1), for age ≥ 1\nMileage adjustment = clamp(−0.000002 × (miles − 12,000 × age), −0.20, +0.20)\nPrivate midpoint = base × (1 + mileage adjustment) × condition × trim\nTrade midpoint = private midpoint × 0.85; retail midpoint = private midpoint × 1.15\nEach scenario range = midpoint × [0.85, 1.15]",explanation:["At age zero, the base equals the original base MSRP. After that, this illustrative curve assumes an 18% first-year loss and 12% annual losses. Expected mileage is 12,000 miles per year; each mile above or below that benchmark adjusts the modeled value by 0.0002%, capped at 20% in either direction.","Condition multipliers are 1.05 for excellent, 1.00 for good, 0.85 for fair, and 0.65 for poor. Trim multipliers are 1.00 for base, 1.05 for mid, and 1.10 for premium. These are UNVERIFIED modeling assumptions, not observed premiums. Use the base model’s original MSRP if selecting a higher trim to avoid counting its premium twice."],example:"A $30,000 original base price, five-year age, 60,000 miles, good condition, and base trim gives an illustrative private-sale midpoint of about $14,752. Its trade midpoint is about $12,540 and retail midpoint about $16,965. The ±15% bands are scenario ranges, not confidence intervals or guaranteed achievable prices.",tips:["Check at least several similar local vehicles, matching model, year, trim, powertrain, and mileage.","Treat advertised prices as asking prices. Record actual written purchase offers separately.","Disclose known damage and title brands. A generic condition dropdown cannot price them reliably.","If you need an insurance, estate, lending, or legal valuation, obtain the appropriate professional appraisal."],sections:[{heading:"What this estimate can and cannot tell you",paragraphs:["The calculator can show how age, usage, and broad condition assumptions affect a transparent baseline. It cannot identify a vehicle, inspect it, confirm a title, or observe a buyer’s willingness to pay. It has no VIN decoding, licensed valuation feed, dealer inventory, or live transaction data. Vehicles with the same MSRP may have very different resale behavior.","Dealer retail, private sale, and trade-in are different transactions. A dealer may incur reconditioning, selling, inventory, and business costs. A private buyer may value records and condition differently. The fixed channel adjustments here only illustrate that distinction; they should not be used to claim that a specific dealer margin is unfair."]},{heading:"Turn a broad range into evidence",paragraphs:["Write down your vehicle’s exact specification and supported mileage. Gather service invoices, title information, and photos of known issues. Compare consistent asking-price evidence and request several written offers with the same disclosures. If those offers cluster far from the model, the offers are more relevant than the generic curve.","For a sale decision, distinguish gross price from net proceeds. Subtract your loan payoff, preparation costs, inspection costs, and any selling fees. A higher private-sale price can require more time and uncertain effort. Compare that net amount with a real trade offer rather than comparing one channel’s midpoint to another channel’s best-case range."]}],faq:[{question:"Does this use live market data?",answer:"No. It uses only the disclosed age, mileage, condition, and trim model. Results are educational estimates rather than appraisals."},{question:"Why can’t I enter a make or VIN?",answer:"There is no vehicle-specific database connected. Asking for a VIN would imply precision the model does not have and would collect information it does not need."},{question:"What do the ranges mean?",answer:"Each is 15% below and above its modeled midpoint. The interval is an illustrative uncertainty band, not a statistically validated prediction interval."},{question:"Can I use kilometers?",answer:"Yes. The calculator converts kilometers to miles using 1 mile = 1.609344 kilometers before applying the mileage assumption."},{question:"How should I choose condition?",answer:"Use a cautious overall assessment. Significant damage, unusual modifications, or title brands require actual inspections and market evidence; a dropdown is not sufficient."}],sources:[ftc,{title:"NMVTIS: Consumer vehicle-history information",url:"https://vehiclehistory.bja.ojp.gov/"}],related:["trade-in-value-estimator","car-depreciation-calculator","used-car-price-negotiation-calculator"]},
ownership:{formula:"Total cost = purchase price − resale value\n  + years × (annual fuel + insurance + maintenance + recurring fees)\n  + upfront taxes/fees + interest paid during ownership\nAnnual fuel = annual miles ÷ US mpg × price per US gallon",explanation:["This is an economic ownership-cost model. Paying the purchase principal acquires an asset; depreciation measures how much of that value is consumed. Counting the full purchase price or every principal payment on top of depreciation would double-count the car. The model therefore includes depreciation and financing interest separately.","Fuel, insurance, maintenance, and recurring taxes or registration are entered as annual averages. Upfront purchase fees are added once and assumed paid in cash. Interest is taken from the modeled loan schedule only for the selected ownership period. If the loan is longer than that period, the remaining balance is displayed for planning the sale."],example:"For a $20,000 cash purchase sold for $10,000 after five years, depreciation is $10,000. At 12,000 miles per year, 30 US mpg, and $3 per gallon, fuel totals $6,000. Add $6,000 insurance, $3,000 maintenance, $500 recurring fees, and $1,000 upfront costs: total economic cost is $26,500, or about $442 per month.",tips:["Get insurance quotes for the actual vehicle before committing to a price.","Use a repair reserve appropriate to the car’s history instead of assuming maintenance will be identical every year.","Compare vehicles over the same years and miles; otherwise the totals answer different questions.","Stress-test a lower resale value and a higher repair budget together."],sections:[{heading:"Build a realistic input set",paragraphs:["Use an expected negotiated price and a conservative resale estimate. Put sales tax, title costs, and cash-paid acquisition fees in the upfront field. Do not include them again in purchase price. For recurring fees, use the registrations or vehicle taxes you expect to pay during each year. State rules are not inferred by this calculator.","Fuel price and insurance defaults are examples, not current averages or quotes. Fuel consumption can vary with traffic, weather, trip length, driving style, and loading. An annual repair allowance is a budget reserve rather than a prediction that repairs will occur evenly. If a major service is already due, include it in your planning rather than smoothing it away without explanation."]},{heading:"Economic cost and cash flow answer different questions",paragraphs:["The average monthly result helps compare vehicles, but it is not a monthly bill. Down payment and fees may be due immediately; repairs arrive unevenly; resale proceeds arrive only when you sell. Keep an emergency fund and separately check whether each month’s loan payment and running expenses fit your actual household cash flow.","The model excludes inflation, investment returns on cash, parking, tolls, charging, business tax deductions, and unusual disposal costs unless you deliberately include suitable amounts in an annual allowance. If resale exceeds purchase price, depreciation becomes negative; review that assumption carefully. A zero annual distance produces no per-mile estimate rather than dividing by zero."]}],faq:[{question:"Why isn’t the entire loan payment added?",answer:"Principal repayment changes your debt and equity; depreciation already accounts for the vehicle value consumed. Only interest is an additional financing cost in this model."},{question:"Does the down payment affect the total?",answer:"It affects the amount borrowed and therefore interest. With a zero-rate loan and no other changes, shifting principal between cash and borrowing does not change economic cost."},{question:"What if I sell before the loan ends?",answer:"The tool counts interest during ownership and shows the remaining balance. Sale proceeds may need to settle that balance; this settlement is not another depreciation expense."},{question:"Are maintenance estimates reliable predictions?",answer:"No. Enter a reserve based on inspection findings and service requirements, then test higher-cost scenarios. Actual repairs can be lumpy and uncertain."},{question:"Can this compare electric vehicles?",answer:"The current fuel model uses US mpg and liquid-fuel prices. It does not calculate kWh consumption; do not treat its fuel result as an EV charging estimate."}],sources:[fuelSource,cfpb,ftc],related:["car-loan-calculator","fuel-cost-calculator","car-depreciation-calculator"]},
affordability:{formula:"Payment budget = max(0, min(0.10 × gross income − running costs,\n  0.36 × gross income − other debts − running costs))\nFinance capacity = payment budget ÷ payment on $1 financed for 48 months\nPurchase budget = min(down payment ÷ 0.20, down payment + finance capacity)",explanation:["The calculation applies three illustrative limits together: at least a 20% down payment, a 48-month loan, and total car expenses within 10% of gross monthly income. It also caps combined other debt and car expenses at 36% of gross income. That extra constraint is a disclosed planning assumption, not a lender’s underwriting standard.","Monthly running costs are subtracted before calculating how much payment is available for financing. The lower of the cash-down limit and the payment-supported limit determines the purchase budget. If no payment capacity remains, the result may still show your available cash as a cash-purchase budget; it does not mean ongoing expenses are affordable."],example:"With $6,000 gross monthly income, $700 of other debt payments, $5,000 down, and $250 of monthly running costs, the 10% guideline leaves $350 for a loan payment. At a 7% annual rate over 48 months, financing capacity is approximately $14,618. The resulting total purchase budget is approximately $19,618 before separating taxes and fees from the vehicle price.",tips:["Include insurance, fuel, routine service, repair reserves, parking, and recurring registration in running costs.","Use reliable income rather than your best commission month or an uncertain overtime estimate.","Keep the down payment separate from an emergency fund and immediate repair cash.","Recheck the result against take-home pay, housing costs, family needs, and savings commitments."],sections:[{heading:"A rule of thumb is a starting point",paragraphs:["Gross income is convenient for a consistent comparison, but taxes and deductions determine what reaches your bank account. Two households with the same salary can have very different room for transportation. Childcare, medical expenses, housing, support obligations, and variable income are not captured in a simple percentage. Use the result to narrow a search, then build a full cash-flow budget.","The 20/4/10 framework is not a legal rule, a guarantee of good financial outcomes, or a promise of loan approval. Some buyers can comfortably spend less; others cannot cover necessary transport within the percentage. A shortfall is useful information: consider a less expensive vehicle, a larger independently affordable down payment, or delaying the transaction."]},{heading:"Work backward from the complete purchase",paragraphs:["Treat the output as a total acquisition budget rather than a listing-price target. If the result is $20,000 and verified taxes and fees total $1,500, a $20,000 sticker price does not fit that same budget. Leave room for inspection, immediate service, and other costs you need to pay without borrowing.","Higher interest reduces the amount financed by a fixed payment. Extending the term can hide that pressure in a low monthly bill while increasing interest and the period of negative-equity risk. This tool deliberately keeps the loan at 48 months; use the separate loan calculator to see the tradeoff explicitly rather than silently changing the guideline."]}],faq:[{question:"Is 20/4/10 an official lending rule?",answer:"No. It is a budgeting guideline implemented here with clearly stated assumptions. Lenders use their own criteria and may approve amounts that are uncomfortable for your household."},{question:"Why is the budget zero with no down payment?",answer:"This version enforces at least 20% down. Zero down cannot satisfy that constraint for a positive purchase price, even if income could support payments."},{question:"Should I enter take-home or gross income?",answer:"The model uses gross monthly income. Check the proposed payment against take-home pay separately before relying on the budget."},{question:"Does the result include insurance?",answer:"Only through the monthly running-cost amount you provide. Get an actual quote and update that number; the tool does not estimate insurance rates."},{question:"What is the 36% limit?",answer:"It is an additional illustrative cap on other debt payments plus modeled transport spending. It is not a standard debt-to-income calculation or an approval threshold."}],sources:[cfpb,{title:"CFPB: Compare auto loan offers",url:"https://www.consumerfinance.gov/ask-cfpb/how-do-i-compare-auto-loan-offers-what-should-i-look-at-besides-the-monthly-payment-en-753/"}],related:["car-loan-calculator","total-cost-of-ownership-calculator","car-sales-tax-calculator"]},
fuel:{formula:"US gallons used = miles ÷ miles per US gallon\nLiters used = kilometers × liters per 100 km ÷ 100\nFuel cost = fuel used × price per matching volume unit\n1 US gallon = 3.785411784 liters; 1 mile = 1.609344 kilometers",explanation:["In US mode, efficiency is miles per US gallon, so a larger number means less fuel for a fixed distance. In metric mode, efficiency is liters per 100 kilometers, so a smaller number means less fuel. The units switch converts the entered distance, fuel price, and efficiency together, with small rounding differences.","The trip estimate and annual estimate use the same fuel economy and price but separate distances. Monthly spending is the annual estimate divided by twelve. This makes it possible to budget a specific journey without accidentally assuming you take that same trip every day. Monetary figures remain USD in either unit system."],example:"A 300-mile trip in a car that averages 30 US mpg consumes about 10 US gallons. At an illustrative $3.50 per gallon, fuel costs $35. For 12,000 annual miles at those same inputs, fuel is $1,400 per year, or approximately $117 per month. These are arithmetic examples, not today’s pump prices.",tips:["Use observed long-run fuel economy where available instead of a best-case dashboard reading.","For a round trip, include the return distance and reasonable local driving.","Test a higher fuel price or worse economy for winter weather, city traffic, towing, or heavy loads.","Keep parking, tolls, lodging, and wear costs separate when comparing travel options."],sections:[{heading:"Make the estimate match your driving",paragraphs:["Official fuel-economy ratings are useful comparison inputs, but your driving pattern may differ from the test cycle. Short trips, cold starts, traffic, speed, tire condition, cargo, and terrain can affect actual consumption. If a car records both trip distance and fuel added across several fill-ups, that longer observation can provide a more relevant estimate than one favorable journey.","Do not mix imperial mpg with US mpg. An imperial gallon is larger, so the same physical fuel economy produces a different mpg figure. This tool offers US gallons and liters only. If your source uses imperial units, convert it before entering a US mpg figure. A kilometers setting changes measurement units; it does not retrieve Canadian or UK fuel prices."]},{heading:"Compare efficiency in dollars",paragraphs:["The relationship between mpg and fuel use is not linear. For the same distance, improving from 20 to 25 mpg saves more gallons than improving from 40 to 45 mpg. Enter both scenarios and save one for comparison to see the actual spending difference. That difference is only one part of choosing a car; an expensive upgrade may take many years to recover through fuel savings.","The sensitivity table varies pump price by 20% above and below your input while holding distance and efficiency fixed. It is a what-if comparison, not a forecast. For a complete budget, add maintenance, depreciation, insurance, and financing in the ownership-cost calculator. Electric charging and plug-in hybrid operating splits need separate energy models and are outside this tool’s scope."]}],faq:[{question:"Are fuel prices updated automatically?",answer:"No. Enter a pump price or a planning assumption. The default is illustrative and is not described as a current national or local average."},{question:"Does metric mode change the currency?",answer:"No. It changes distance, consumption, and volume units. Prices and results remain USD, so use a USD-equivalent price if necessary."},{question:"Why did numbers change when I switched units?",answer:"Distance, efficiency, and price are converted to preserve approximately the same physical scenario. Rounding can produce a small difference in the displayed cost."},{question:"Can I enter zero miles?",answer:"Yes. A zero-distance trip costs zero in this model. Efficiency must stay above zero to keep consumption meaningful."},{question:"Does this estimate electric charging costs?",answer:"No. It models liquid fuel only. Electric vehicles require kWh consumption, charging losses, and electricity pricing instead of mpg."}],sources:[fuelSource],related:["total-cost-of-ownership-calculator","car-affordability-calculator","car-depreciation-calculator"]},
trade:{formula:"Private midpoint = age-depreciated original base MSRP × mileage × condition × trim adjustments\nTrade midpoint = private midpoint × 0.85\nTrade scenario band = midpoint × [0.85, 1.15]\nNet trade equity = estimated trade value − current loan payoff",explanation:["The underlying illustrative valuation starts with an 18% decline in the first year and 12% in each later year. At age zero it retains the starting MSRP. Expected mileage is 12,000 miles per year, with an adjustment of 0.0002% per mile above or below that benchmark, capped at ±20%. Kilometers are converted before that adjustment.","Good condition and base trim have a 1.00 multiplier. Excellent, fair, and poor conditions use 1.05, 0.85, and 0.65. Mid and premium trim use 1.05 and 1.10. The trade midpoint is 85% of the private midpoint. Every coefficient is an illustrative modeling choice, not a measured dealer discount or a licensed valuation."],example:"For a five-year-old car with $30,000 original base MSRP, 60,000 miles, good condition, and base trim, the modeled trade midpoint is about $12,540. With an $8,000 payoff, midpoint equity is about $4,540. If a real dealer offer is $11,000, that actual offer replaces the modeled amount in your purchase budget.",tips:["Get written offers close together in time and disclose the same condition details to each buyer.","Keep replacement-car price, trade allowance, loan payoff, and financing as separate line items.","Ask your lender for the payoff amount and the process for confirming that the old debt is settled.","Verify any trade-related tax treatment with the state authority rather than assuming it applies."],sections:[{heading:"The trade allowance is only one line in the deal",paragraphs:["A generous-looking allowance can be offset by a higher replacement-car price, added products, or less favorable financing. Compare complete written deals on the same vehicle and assumptions. Record the vehicle price before trade, taxes and fees, the trade allowance, payoff, cash down, amount financed, rate, and term. A combined monthly-payment discussion makes those tradeoffs harder to see.","The range displayed here is ±15% around a generic midpoint. It is not a promise that a dealer will buy within that band. Reconditioning needs, title history, local inventory, demand, and the specific model may dominate the calculation. A dealer’s inspection and actual written offer provide evidence this tool does not have."]},{heading:"Plan for positive or negative equity",paragraphs:["Positive equity means the offer exceeds the payoff, leaving value that may contribute toward the next purchase. Negative equity means the old debt is larger than the offer. Rolling that difference into a new loan increases the new principal; it does not make the old debt disappear. You can model that amount directly in the loan calculator.","A private sale may produce more gross proceeds but require preparation, advertising, appointments, secure payment, and lien-release coordination. Compare net proceeds and effort, not just the highest asking price you saw online. Before handing over keys or title, verify the transfer process with your lender and state motor-vehicle agency. Keep confirmation that the previous loan was paid."]}],faq:[{question:"Is this a guaranteed cash offer?",answer:"No. There is no dealer network or live offer integration. This is a disclosed planning model for a broad range and possible equity."},{question:"Why is trade-in below private sale?",answer:"The model applies an illustrative 15% channel reduction. It represents a scenario, not a factual fixed margin for every dealer or vehicle."},{question:"Can a trade increase my next loan?",answer:"Yes. If payoff exceeds the trade allowance, the difference must be paid or financed. The loan calculator can show its effect on payment and interest."},{question:"Does the estimate include a tax saving?",answer:"No. Tax treatment depends on the transaction and jurisdiction. Enter only a verified allowed credit in the separate tax calculator."},{question:"What should I use as the payoff amount?",answer:"Use a lender payoff quote valid for the expected transaction date. A statement balance may not include all accrued interest or applicable charges."}],sources:[cfpb,ftc],related:["what-is-my-car-worth","car-loan-calculator","car-sales-tax-calculator"]},
lease:{formula:"Buy equity at end = resale value − remaining loan balance\nBuy net cost = down payment + loan payments made − end equity\nLease total = extra upfront cash + monthly payment × comparison months\n  + other lease fees + total excess miles × per-mile charge",explanation:["Both options are compared over the same period, which should match the quoted lease term. Buying assumes the vehicle is sold at the end, so the remaining equity is recovered. If the loan balance exceeds resale value, equity is negative and increases the modeled buying cost. A paid-off car still has a residual asset value.","The lease inputs start from an actual quoted monthly payment rather than attempting to derive an offer from a money factor. Include monthly tax in that payment. Extra upfront cash excludes the first monthly installment because all installments are already counted; otherwise the first payment would be counted twice. Exclude refundable deposits."],example:"Buy a $20,000 vehicle with $2,000 down and a zero-rate, 60-month loan. After 36 months, you have made $10,800 in payments and owe $7,200. If resale is $12,000, equity is $4,800 and net buying cost is $8,000. A lease at $250 for 36 months plus $1,000 upfront, $300 fees, and $250 mileage charges costs $10,550.",tips:["Use similar vehicles and the same horizon. A three-year lease and five years of buying answer different questions.","Read the lease’s mileage allowance, excess-mile charge, wear rules, and end-of-term fees.","Include taxes consistently and ensure acquisition or disposition fees are not already counted elsewhere.","Run a lower resale scenario for buying and a higher-mileage scenario for leasing."],sections:[{heading:"Cash paid is different from cost consumed",paragraphs:["Buying may require larger monthly payments but leave an asset at the end. Leasing generally leaves no ownership equity unless a separate purchase is made. Simply adding payments and comparing those sums misses that distinction. This model subtracts estimated end equity from buying cash paid so the comparison reflects value retained.","The resale estimate is uncertain, and it can change the ranking. If you intend to keep the purchased car rather than sell it, the equity is not cash in your account even though it remains part of your net position. Check both economic cost and the actual cash you must spend during the term."]},{heading:"Keep the contract details visible",paragraphs:["This calculator does not assess the reasonableness of a lease’s money factor, residual, acquisition charge, or early-termination terms. Enter the complete written quote, including applicable taxes and fees, and read restrictions before comparing. An advertised payment may exclude upfront amounts, tax, or eligibility conditions that materially change the total.","Fuel, insurance, maintenance, repairs, and opportunity cost are excluded from both columns. If those expenses differ between the vehicles, the displayed gap is incomplete. Leasing a new car and buying an older used car may involve different warranties and maintenance exposure. List those differences separately or use ownership-cost scenarios to supplement the comparison."]}],faq:[{question:"Does this calculate a lease payment from a money factor?",answer:"No. Enter the payment from a written quote. The tool compares total costs over an equal period; it does not generate a lease offer."},{question:"Should first month’s payment go in upfront cash?",answer:"No. The monthly payment is multiplied by the full comparison term. Enter only additional nonrefundable upfront cash to avoid counting the first payment twice."},{question:"What if my loan lasts longer than the lease?",answer:"The remaining balance at the comparison date is subtracted from resale value to determine equity. The full loan is not assumed paid off early for free."},{question:"Is lease-end buyout included?",answer:"No. This scenario assumes the leased vehicle is returned. A buyout requires a separate analysis of the purchase option, fees, taxes, and financing."},{question:"Does the lower result tell me what to choose?",answer:"It identifies the cheaper modeled scenario under your inputs. Mileage flexibility, ownership plans, contract restrictions, and uncertain operating costs still matter."}],sources:[cfpb,{title:"FTC: Financing or leasing a car",url:"https://consumer.ftc.gov/articles/financing-or-leasing-car"}],related:["car-loan-calculator","total-cost-of-ownership-calculator","car-affordability-calculator"]},
inspection:{formula:"Recorded progress = (checked + concerns + not applicable) ÷ 25 × 100\nConcern count = number of items marked Concern\nProgress is record completion, not a safety score.",explanation:["The checklist groups 25 observations into identity and paperwork, exterior and tires, cabin and controls, mechanical observations, and the test drive. Every item starts as not checked. Mark it checked only after you have actually looked at the relevant evidence; mark a concern when it needs follow-up, or not applicable when appropriate.","The progress figure counts all recorded decisions, including concerns. Reaching 100% does not mean the car passed an inspection. It means you have assigned a status to each prompt. Your mechanic can use the flagged items as a starting point, but their professional inspection should be broader than this consumer checklist."],example:"If you record 12 checked items, three concerns, and two not-applicable items, progress is 17 of 25, or 68%. The summary shows three concerns. Before committing, resolve those concerns and investigate the remaining eight unchecked items. Printing the summary helps preserve a consistent set of observations across several vehicles.",tips:["Arrange daylight, a safe location, seller permission, and enough time before the appointment.","Ask to observe a cold start when practical. Do not touch hot or moving components.","Never get beneath a vehicle supported only by an emergency jack.","Pay for an independent inspection and request written findings before deciding."],sections:[{heading:"Start with identity and records",paragraphs:["Match the VIN on the car with the title, listing, and service documents. Check the seller’s authority to transfer it and clarify any lien before money changes hands. Review available vehicle-history information and search for recalls. A history report cannot prove that every accident or repair was reported, and a recall search does not inspect the current mechanical condition.","For a dealer sale, read the Buyers Guide and understand whether the car is offered with a warranty or as is. Get repair promises and important representations in writing. If access to a reasonable independent inspection is refused, that limits your evidence even if the car looks clean or the listing describes it as certified."]},{heading:"Observe safely, then ask an expert",paragraphs:["During the walkaround, note mismatched panels, corrosion, tire wear, broken lights, water marks, unusual odors, and other observations without jumping to a diagnosis. During a permitted test drive, observe ordinary braking, steering, transmission behavior, and warning lamps on a safe route. Do not perform aggressive maneuvers or tests beyond your ability.","A concern is a question to investigate, not automatically a defect or a bargaining amount. Ask an independent mechanic about cause, severity, urgency, and a written repair estimate. Structural damage, safety systems, flood exposure, and high-voltage components may require specialists. An unresolved major issue can justify pausing rather than merely negotiating a lower price."]},{heading:"Keep useful notes without oversharing",paragraphs:["A share link stores only the checklist statuses in the URL. It does not upload a VIN, seller details, photos, or a vehicle report. Anyone who has the link can see those statuses, so keep private supporting documents elsewhere. Download the findings for your records and create a fresh checklist when viewing another car."]}],faq:[{question:"Does a completed checklist mean the car is safe?",answer:"No. Completion measures recorded observations only. It is not a certification, mechanical diagnosis, or substitute for an independent inspection."},{question:"Will my checklist survive a reload?",answer:"Statuses are reflected in the page URL. Reloading that URL or opening a copied link restores them. Reset removes the recorded statuses from the URL."},{question:"Can I share it with a mechanic?",answer:"Yes. Copy the result link, print the page, or download the findings. Add private supporting documents separately through a method you trust."},{question:"What should I do with a concern?",answer:"Ask for an explanation and independent evidence. Record a written repair estimate when appropriate. Do not proceed with unresolved identity, title, or serious safety questions."},{question:"Does a clean history report replace inspection?",answer:"No. History databases can be incomplete and do not establish present mechanical condition. Use reports, records, recall checks, and an independent inspection together."}],sources:[ftc,{title:"NHTSA: Check vehicle recalls",url:"https://www.nhtsa.gov/recalls"},{title:"NMVTIS: Vehicle-history resources",url:"https://vehiclehistory.bja.ojp.gov/"}],related:["used-car-price-negotiation-calculator","what-is-my-car-worth","total-cost-of-ownership-calculator"]},
negotiation:{formula:"Vehicle-price ceiling = supported comparable value − repair deductions\nOpening offer = ceiling × (1 − chosen discount/100)\nOffer with entered fees = opening offer + known taxes and fees",explanation:["Begin with a comparable value you can explain: similar year, model, trim, powertrain, mileage, condition, and local market. The calculator does not retrieve comparable sales or verify that value. Deduct documented repair costs only when the baseline does not already reflect those same issues.","The opening discount is chosen by you. The default 5% demonstrates the arithmetic; it is not evidence of a typical negotiating margin. The vehicle-price ceiling is a reference point after repairs, and known taxes or fees are added separately so the offer is not confused with the complete transaction price."],example:"A supported $20,000 comparable value minus $1,000 of repairs gives a $19,000 vehicle-price ceiling. A 5% opening discount produces an $18,050 opening offer. Adding $500 in known fees gives $18,550 before any taxes or costs not included in that fee input. The seller is free to accept, counter, or decline.",tips:["Bring specific comparable listings and explain meaningful differences, rather than relying on a broad average.","Use written inspection findings to support repairs; do not subtract the same condition issue twice.","Ask for an itemized out-the-door total and check optional products separately.","Set a walk-away budget before negotiating and leave room for initial maintenance."],sections:[{heading:"Build evidence before choosing a number",paragraphs:["An opening offer is more defensible when it follows evidence. Record the comparable’s specification, mileage, advertised price, location, and any known fees. A listing that omits important charges is not directly comparable with an all-in offer. Asking prices also do not prove what buyers ultimately paid, so avoid presenting them as confirmed transactions.","Repairs need context. An immediate safety repair, a routine service due soon, and a cosmetic preference are different categories. A vehicle already priced in rough condition may not justify subtracting every restoration cost from a clean-car value without further adjustment. If repairs exceed the entire comparable value, this tool refuses the calculation and asks you to reassess."]},{heading:"Separate negotiation from the decision to buy",paragraphs:["A lower price does not resolve an uncertain title, suspected structural damage, unverified mileage, or a refused inspection. Those issues can change whether you should buy at all. Treat the ceiling as a planning reference rather than a command to purchase if the seller reaches it. Your household budget and alternative vehicles remain relevant.","The tool accepts a combined amount for known taxes and fees, but some taxes change with the final agreed price. Recalculate them and review the final written deal before signing. Keep the replacement-car price, trade allowance, old loan payoff, optional products, and loan terms separate. A payment-only negotiation can hide increases elsewhere in the transaction."]}],faq:[{question:"Is a 5% discount usually achievable?",answer:"The calculator makes no such claim. It is an editable scenario input. Seller flexibility depends on the vehicle, competition, demand, and the supported asking price."},{question:"Where should comparable value come from?",answer:"Use relevant local evidence and actual offers where available. Match the key vehicle characteristics and distinguish asking prices from completed transactions."},{question:"Should I deduct every inspection finding?",answer:"Only apply a supported adjustment that is not already included in the baseline. Some findings change the decision to buy rather than simply producing a repair discount."},{question:"Are taxes recalculated automatically?",answer:"No. Enter known taxes and fees, then refresh them when the agreed vehicle price changes. The sales-tax calculator can help with a verified rate and taxable base."},{question:"Does the ceiling replace my personal budget?",answer:"No. Your maximum should also reflect affordability, immediate repairs, and the alternatives available. A modeled market ceiling may exceed what you can comfortably spend."}],sources:[ftc,cfpb],related:["used-car-inspection-checklist","car-sales-tax-calculator","car-affordability-calculator"]},
tax:{formula:"Taxable base = vehicle price + taxable fees − verified allowed credit\nEstimated tax = taxable base × combined rate/100\nPurchase total = vehicle price + taxable fees + tax + nontaxable fees\nTrade payment, loan payoff, and down payment are handled separately.",explanation:["Enter the rate applicable to your transaction after verifying it with the relevant authority. The 6% default is an arithmetic example, not a rate assigned to any state. The state selector provides official agency entry points only. It does not know your address, tax district, residency, sale type, exemptions, or current legislation.","The allowed credit reduces the tax base. It does not represent a cash payment in the purchase total. For example, a trade-related tax credit and the trade allowance used to settle the purchase are related but different line items. Deduct the actual allowance separately when calculating the amount you must pay or finance."],example:"For a $20,000 vehicle, $500 taxable fees, a verified $5,000 allowed tax-base credit, and an illustrative 6% rate, the taxable base is $15,500 and tax is $930. With $200 nontaxable fees, the purchase total before trade payment and down payment is $21,630. The example does not establish that any jurisdiction permits those inputs.",tips:["Verify rules for where the vehicle will be titled or registered and for the specific type of transaction.","Ask which dealer charges are taxable and whether the same rate applies to each one.","Confirm whether trade allowances, rebates, private sales, or exemptions change the tax base.","Obtain a written itemization and compare it with the authority’s official calculator or instructions."],sections:[{heading:"Why a state name is not enough",paragraphs:["Vehicle tax treatment can depend on state and local jurisdictions, residency, dealer versus private sale, vehicle classification, and the timing or structure of a trade. Some systems use different taxes, value measures, caps, or exemptions. A single state-wide percentage can therefore produce a misleading result for a particular purchase.","This tool intentionally asks for a verified combined rate and allowed credit instead of maintaining an unverified table of current rates. The directory helps you start with official information, but the correct calculation may require a local office or additional authority. Check the original agency instructions and effective rules rather than relying on a search snippet or an old dealer estimate."]},{heading:"Know when the simplified model does not fit",paragraphs:["The formula assumes one percentage applied to one taxable base. It does not handle tax caps, brackets, separately taxed charges, use-tax offsets for another jurisdiction, unusual valuation rules, or conditional rebates. If those apply, use the authority’s method and treat this result only as a partial illustration. The tool rejects a credit larger than the taxable purchase amount rather than inventing a refund.","An out-the-door total also needs the actual title, registration, plate, inspection, and dealer charges that apply to the deal. Enter only fees you have verified, and avoid classifying a charge as nontaxable merely because it appears on a separate line. After the purchase price changes in negotiation, recompute tax and review the final paperwork for duplicate or optional charges."]}],faq:[{question:"Does selecting a state fill in its tax rate?",answer:"No. It links to an official agency resource. Rates and allowed credits remain inputs you must verify for your transaction."},{question:"Is the default 6% a current state rate?",answer:"No. It is a hypothetical example. Replace it before using the result to plan a real purchase."},{question:"Does every state allow a trade-in credit?",answer:"The tool makes no universal claim. Verify whether a credit applies, what amount is allowed, and whether the transaction must meet specific conditions."},{question:"Why isn’t my trade deducted from the purchase total?",answer:"The entered credit changes tax calculation only. The actual trade allowance is a separate payment toward the deal and belongs in the loan or settlement calculation."},{question:"Can I use this for a UK or Canadian purchase?",answer:"The arithmetic is generic, but this page’s resources and assumptions are US-focused. It does not implement UK or Canadian tax rules, currencies, or regional requirements."}],sources:[{title:"USA.gov: State motor-vehicle services",url:"https://www.usa.gov/state-motor-vehicle-services"},{title:"Texas Comptroller: Motor vehicle tax",url:"https://comptroller.texas.gov/taxes/motor-vehicle/"},{title:"California DMV: Vehicle registration fees",url:"https://www.dmv.ca.gov/portal/vehicle-registration/registration-fees/"}],related:["car-loan-calculator","used-car-price-negotiation-calculator","trade-in-value-estimator"]},
};
